function UIBattlingElementBreakPanel:InitComponent()
    --- 初始化描述界面相关
    self.GRRShowPanel = self.Btn_ShowInfoPanel:GetComponent(typeof(GraphicRaycastReceiver))
    local luaBehaviour = GetLuaBehaviour(self.Root_ElementBreakDes.gameObject, PATH_LUATABLE_ELEMENTBREAKINFO)
    luaBehaviour:Init()
    self.luaTableElementBreakInfo = luaBehaviour.Env
    local canvas = KTool.GetOrAddComponent(self.Root_ElementBreakDes.gameObject, typeof(CS.UnityEngine.Canvas))
    if not IsNull(canvas) then
        canvas.overrideSorting = true
        canvas.sortingOrder = 2
    end
    --- 初始化sleep回合数
    local transRoundsTxt = self.RootStateLock:Find("Text")
    if not IsNull(transRoundsTxt) then
        self.txtRootLockedRounds = transRoundsTxt.gameObject:GetComponent(typeof(Text))
    end
    --- 初始化狂暴动画控制器
    self.animRootStateBreakStar = KTool.GetComponent(self.RootStateBreakStar.gameObject, typeof(Animation))
    local loopAnimation = self.animRootStateBreakStar:get_Item(ANIMATION_BREAK_LOOP)
    loopAnimation.layer = 1
    loopAnimation.blendMode = AnimationBlendMode.Additive   -- 把loop动画放到单独的层里面做addtive，不然播放hurt的时候会打断loop
    --- 初始化虚弱动画控制器
    self.animRootStateBreaking = KTool.GetComponent(self.RootStateBreaking.gameObject, typeof(Animator))

    --- 初始化狂暴条
    self.TopSliderRoot:Init()
    self.MidSliderRoot:Init()
    self.LB_topSlider = self.TopSliderRoot.Env
    self.LB_midSlider = self.MidSliderRoot.Env
    self.LB_topSlider:SetProgress(1)
    self.LB_midSlider:SetProgress(1)
    -- 初始化狂暴预扣提示
    self.preTipsCanvasGroup = KTool.GetComponent(self.PreTxt.gameObject, typeof(CanvasGroup))
    self.preTipsRectTransform = KTool.GetComponent(self.PreTxt.gameObject, typeof(RectTransform))

    self.lerpAnimationCurve = CS.UnityEngine.AnimationCurve.Linear(0,0,1,1)
end

function UIBattlingElementBreakPanel:InitListener()
    -- 显示描述
    KTool.GetOrAddComponent(self.Btn_ShowInfoPanel.gameObject, typeof(UIEventProxy)).onPointerClick = Bind(self, self.ActionOnBtnShowInfoClick)
    -- 关闭描述
    KTool.GetOrAddComponent(self.Btn_ClosePanel.gameObject, typeof(UIEventProxy)).onPointerClick = function()
        self.luaTableElementBreakInfo:ShowPanel(false)
        KTool.SetActive(self.Btn_ClosePanel.gameObject, false)
    end
    -- 敌对阵营技能结束时，扣除狂暴值
    self.eventBattleElementBreak = Events.AddListener(Constants.EventNames.BattleElementBreak, Bind(self, self.BattleElementBreakFun))
    -- 添加狂暴buff，开始狂暴
    self.eventBattleWeakExpose = Events.AddListener(Constants.EventNames.BattleWeakExpose, Bind(self, self.BattleWeakExposeFun))
    -- 添加虚弱buff，开始虚弱
    self.eventBattleWeak = Events.AddListener(Constants.EventNames.BattleWeak, Bind(self, self.BattleWeak))
    -- 玩家使用卡牌的时候，预扣狂暴值
    self.eventInputUseCard = Events.AddListener(Constants.EventNames.UIBattlingUseSkillCard, Bind(self, self.OnInputUseSkillCard))
    -- 战斗开始时，复原预扣的狂暴值
    self.eventInputOver = Events.AddListener(Constants.EventNames.BattleInputFinished, Bind(self, self.OnInputOver))
    -- 玩家重置出牌序列，复原预扣的狂暴值
    self.eventInputResetCard = Events.AddListener(Constants.EventNames.BattleInputReset, Bind(self, self.OnInputResetSkillCard))
end

function UIBattlingElementBreakPanel:RemoveListener()
    Events.RemoveListener(Constants.EventNames.BattleElementBreak, self.eventBattleElementBreak)
    Events.RemoveListener(Constants.EventNames.BattleWeakExpose, self.eventBattleWeakExpose)
    Events.RemoveListener(Constants.EventNames.BattleWeak, self.eventBattleWeak)
    Events.RemoveListener(Constants.EventNames.UIBattlingUseSkillCard, self.eventInputUseCard)
    Events.RemoveListener(Constants.EventNames.BattleInputFinished, self.eventInputOver)
    Events.RemoveListener(Constants.EventNames.BattleInputReset, self.eventInputResetCard)
    if self.eventCheckSleep then
        Events.RemoveListener(Constants.EventNames.BattleTurnStartShow, self.eventCheckSleep)
    end
end

