---PanelShowState
---切换界面显示状态
---@param state integer @ PanelShowState 显示状态
function UIBattlingElementBreakPanel:PanelShowState(state)
    xTry(function()
        self.typeShowState = state
        if state == PanelShowState.Sleep then
            KTool.SetActive(self.RootStateLock.gameObject, true)
            KTool.SetActive(self.RootStateBreakStar.gameObject,false)
            KTool.SetActive(self.RootStateBreaking.gameObject, false)
            --- 加载 狂暴锁定特效
            self.numWaitingRounds = self.weaknessData.sleepLength
            self.eventCheckSleep = Events.AddListener(Constants.EventNames.BattleTurnStartShow, Bind(self, self.UpdateSleepLength))
            self:SwitchBossHeadBg(state)
        elseif state == PanelShowState.Running then
            if self.eventCheckSleep then
                Events.RemoveListener(Constants.EventNames.BattleTurnStartShow, self.eventCheckSleep)
            end
            KTool.SetActive(self.RootStateLock.gameObject, false)
            KTool.SetActive(self.RootStateBreakStar.gameObject,true)
            KTool.SetActive(self.RootStateBreaking.gameObject, false)
            self.numBossWeakStarsMax = self.numBossWeakStars
            self.TxtStarCount_Now.text = checkString(self.numBossWeakStarsMax)
            -- self.TxtStarCount_EX.text = string.format("/%s", checkString( self.numBossWeakStarsMax))
            self.animRootStateBreakStar:Play(ANIMATION_BREAK_ENTER)
            self.animRootStateBreakStar:PlayQueued(ANIMATION_BREAK_LOOP)
            self:SwitchBossHeadBg(state)
        elseif state == PanelShowState.Weakness then
            KTool.SetActive(self.RootStateLock.gameObject, false)
            KTool.SetActive(self.RootStateBreakStar.gameObject,false)
            KTool.SetActive(self.RootStateBreaking.gameObject, true)
            self.animRootStateBreaking:Play("StateBreaking")
            self:SwitchBossHeadBg(state)
        elseif state == PanelShowState.Out then
            self:SetPanelRootState(false)
            self:SwitchBossHeadBg(state)
        end
        local bossMsg = { type = 4, data = { state = state } }
        Events.Broadcast(Constants.EventNames.UIBattlingBossMsg, bossMsg)
    end)
end
