---InitPanel
---初始化元素击破面板信息
---@param effectId number
function UIBattlingElementBreakPanel:InitPanel(effectId)
    xTry(function()
        self.weaknessData = clone(UIBattlingTools.GetWeaknessDataByRefId(effectId))
        local weaknessList = self.weaknessData.weakStars        -- 这是一个数组，数组里面是每一轮解除狂暴需要的星数
        if not IsNull(weaknessList) or #weaknessList > 0 then
            --- 初始化列表序号
            self.indexElementList = 1
            --- 赋值 当前轮次 需要的星数
            self.numBossWeakStars = weaknessList[self.indexElementList]
        end
        --- 设置解体描述界面信息
        self.luaTableElementBreakInfo:SetWeaknessData(self.weaknessData)
        --- 设置界面显示状态
        --self:PanelShowState(PanelShowState.Sleep)
        --- 首次执行自动提示
        --self:CoroutineShowTips()
    end)
end

