---UpdateSleepLength
---更新 解体休眠 时长
function UIBattlingElementBreakPanel:UpdateSleepLength(data)
    local isMineTurn = data.isMyTurn
    if isMineTurn then
        self.numWaitingRounds = self.numWaitingRounds - 0.5
        local value = checkInt(math.ceil(self.numWaitingRounds))
        if not IsNull(self.txtRootLockedRounds) then
            self.txtRootLockedRounds.text = string.format("%d%s", value, LOCALIZE_ROUND)
        end
        if not isNull(self.luaTableElementBreakInfo) then
            self.luaTableElementBreakInfo:SetBreakWaitingLength(value)
        end
    end
end

---CheckRound
---检查回合数
---@param data table {uid=1, ownerId=1, lay=1, remain=1}
function UIBattlingElementBreakPanel:CheckRound(data)
    if data.uid == self.idCharacterWeakBuff then
        self.TxtBreakingRoundNum.text = checkInt(math.ceil(data.remain))
    end
end

---RemoveWeakBuff
---虚弱 Buff 移除
---@param data table {uid=1, ownerId=1}
function UIBattlingElementBreakPanel:RemoveWeakBuff(data)
    if data.uid == self.idCharacterWeakBuff then
        self:CheckAndRunNextStep()
        self.idCharacterWeakBuff = nil
        Events.RemoveListener(Constants.EventNames.BattleChangeBuffShow, self.eventCheckRound)
        self.eventCheckRound = nil
        Events.RemoveListener(Constants.EventNames.BattleRemoveBuffShow, self.eventAfterWeak)
        self.eventAfterWeak = nil
    end
end

---CheckAndRunNextStep
---检查并执行后续逻辑
function UIBattlingElementBreakPanel:CheckAndRunNextStep()
    if self.indexElementList >= #self.weaknessData.weakStars then
        --- 后面没有
        self:PanelShowState(PanelShowState.Out)
    else
        --- 后面还有
        self.indexElementList = self.indexElementList + 1
        self.numBossWeakStars = self.weaknessData.weakStars[self.indexElementList]
        self:PanelShowState(PanelShowState.Sleep)
    end
end

--- 玩家使用卡牌时，预扣狂暴值
function UIBattlingElementBreakPanel:OnInputUseSkillCard(useSkillCardRecord)
    if not self.isPreTipsActive then
        self:SetPreDecreaseTipsPosition()
        self:ShowPreDecreaseTips()
        self.curPreTipsValue = 0
    end
    local star = useSkillCardRecord.s
    self:PreDecreaseElementBreakValue(star)
end

--- 玩家输入结束，开始战斗，复原狂暴值并隐藏预扣提示
function UIBattlingElementBreakPanel:OnInputOver()
    self:ResetPreDecreaseElementBreakValue()
    self:HidePreDecreaseTips()
end

--- 玩家重置出牌序列，复原预扣的狂暴值
function UIBattlingElementBreakPanel:OnInputResetSkillCard()
    self:ResetPreDecreaseElementBreakValue()
    self:HidePreDecreaseTips()
end

---BattleElementBreakFun
---弱点暴露状态属性破坏(消星)
---@param data table @ {roleId = 1, stars = 1}
function UIBattlingElementBreakPanel:BattleElementBreakFun(data)
    if IsNull(self.idRoleWeakExpose) or self.idRoleWeakExpose ~= data.roleId then return end
    local num = data.stars
    --- 消除的狂暴星数量 数值 > 0 保护 
    -- num = self.numBossWeakStarsMax - num
    self:AnimationElementBreak(num)
end

function UIBattlingElementBreakPanel:AnimationElementBreak(num, numEx)
    self.numBossWeakStars = num >= self.numBossWeakStarsMax and self.numBossWeakStarsMax or num
    if not IsNull(self.TxtStarCount_Now) then
        self.TxtStarCount_Now.text = self.numBossWeakStars
    end
    if not IsNull(self.animRootStateBreakStar) then
        self.animRootStateBreakStar:Play(ANIMATION_BREAK_HURT)
    end
    --- 设置狂暴条进度
    self:SetElementBreakValue()
end

---BattleWeakExposeFun
---弱点暴露(开始狂暴)
---@param data table @ {roleId = 1, element = {1, 2, 2}}
function UIBattlingElementBreakPanel:BattleWeakExposeFun(data)
    -- print("->UIBattlingElementBreakPanel:BattleWeakExposeFun")
    self:PanelShowState(PanelShowState.Running)
    self.idRoleWeakExpose = data.roleId
    self.TxtStarCount_Now.text = checkString(self.numBossWeakStarsMax)
    --checkString(self.numBossWeakStars)
    --- 首次执行自动提示
    if self.indexElementList == 1 then
        self:CoroutineShowTips()
    end
end

---BattleWeak
---解除弱点暴露状态，进入虚弱状态（完成狂暴, Boss虚弱）
---@param data table @ {roleId = 1}
function UIBattlingElementBreakPanel:BattleWeak(data)
    -- print("->UIBattlingElementBreakPanel:BattleWeak")
    --TODO 记录协程引用
    CoWait.WaitTime(0.5, function()
        self:PanelShowState(PanelShowState.Weakness)
        self.idRoleWeakExpose = nil
        ---监听 虚弱时长
        local weakLength = self.weaknessData.weakLength
        if weakLength == 0 or weakLength == "" or IsNull(weakLength) then
            self:CheckAndRunNextStep()
        else
            self.TxtBreakingRoundNum.text = checkInt(math.ceil(weakLength)) --设置 Boss 狂暴回合数
            local charactorBuffs = clone(BattleViewMgr:FindRoleView(data.roleId).buffViewMgr.buffs)
            for i = 1, #charactorBuffs do
                local buff = charactorBuffs[i]
                local mainEffect = buff.data.effects[1] --- 主效果Id
                local mainEffectType = -1
                local subEffectType = -1
                local miniEffectType = -1
                --- 获取 效果数据
                local buffEffectData = Core:GetBuffEffectData(mainEffect, buff.data.star, buff.data.lv, buff.data.upgradeType)
                if buffEffectData then
                    mainEffectType = buffEffectData.mainEffectType
                    subEffectType = buffEffectData.subEffectType
                    miniEffectType = buffEffectData.miniEffectType
                end
                --- 判断 buff 效果是否为弱点
                if mainEffectType == Constants.BuffType.Special and subEffectType == Constants.SpecialBuffType.Weak then
                    self.idCharacterWeakBuff = buff.id
                end
            end
        end
        self.eventCheckRound = Events.AddListener(Constants.EventNames.BattleChangeBuffShow, Bind(self, self.CheckRound))
        self.eventAfterWeak = Events.AddListener(Constants.EventNames.BattleRemoveBuffShow, Bind(self, self.RemoveWeakBuff))
        --- 首次执行自动提示
        if self.indexElementList == 1 then
            self:CoroutineShowTips()
        end
    end)
end
