---CoroutineShowTips
---展示 当前阶段 提示描述 并 自动隐藏
function UIBattlingElementBreakPanel:CoroutineShowTips()
    self.coShowDesc = cs_coroutine.start(function()
        self.GRRShowPanel.enabled = false
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.8))
        self:ShowBreakInfo()
        self.luaTableElementBreakInfo:ShowPanel(true)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(2))
        self.luaTableElementBreakInfo:ShowPanel(false)
        self.GRRShowPanel.enabled = true
        self.coShowDesc = nil
    end)
end

--- 玩家使用卡牌时，预扣狂暴值（仅ui表现）
function UIBattlingElementBreakPanel:PreDecreaseElementBreakValue(value)
    self.curPreTipsValue = self.curPreTipsValue + value
    self.PreTxt.text = -self.curPreTipsValue
    local curStar = self.numBossWeakStars - self.curPreTipsValue
    local progress = curStar / self.numBossWeakStarsMax
    self.LB_topSlider:LerpProgress(progress, 0.12, self.lerpAnimationCurve)
end

--- 复原预扣的狂暴值（仅ui表现）
function UIBattlingElementBreakPanel:ResetPreDecreaseElementBreakValue()
    self.curPreTipsValue = 0
    self.PreTxt.text = -self.curPreTipsValue
    local progress = self.numBossWeakStars / self.numBossWeakStarsMax
    self.LB_topSlider:LerpProgress(progress, 0.12, self.lerpAnimationCurve)
end

--- 显示预扣狂暴值的ui提示
function UIBattlingElementBreakPanel:ShowPreDecreaseTips()
    self.isPreTipsActive = true
    self.preTipsCanvasGroup.alpha = 1
end

--- 隐藏预扣狂暴值的ui提示
function UIBattlingElementBreakPanel:HidePreDecreaseTips()
    self.isPreTipsActive = false
    self.preTipsCanvasGroup.alpha = 0
end

--- 设置预扣值提示的位置
function UIBattlingElementBreakPanel:SetPreDecreaseTipsPosition()
    local handlePosition = self.LB_midSlider.ui.handleRect.localPosition
    self.preTipsRectTransform.localPosition = handlePosition
end

--- 获取预扣值提示的世界位置
function UIBattlingElementBreakPanel:GetPreDecreaseTipsWorldPosition()
    return self.LB_topSlider.ui.handleRect.position
end

--- 正式的（非预扣） 设置狂暴条
function UIBattlingElementBreakPanel:SetElementBreakValue()
    local progress = self.numBossWeakStars / self.numBossWeakStarsMax
    self.LB_topSlider:LerpProgress(progress, 0.12, self.lerpAnimationCurve)
    CoWait.WaitTime(0.5, function ()
        self.LB_midSlider:LerpProgress(progress, 0.12, self.lerpAnimationCurve)
    end)
end

function UIBattlingElementBreakPanel:SwitchBossHeadBg(state)
    local luaEnv_bossInfoPanel = UIBattlingCtrlMgr:GetInstance():GetBattleBossInfoPanel()
    luaEnv_bossInfoPanel:SwitchBossHeadBg(state)
end

--- 显示预扣狂暴值的特效
function UIBattlingElementBreakPanel:ShowPreDecreaseEffect()
    if self.PTC_ElementBreakPreDecrease then
        KTool.SetActive(self.PTC_ElementBreakPreDecrease.gameObject, false)
        KTool.SetActive(self.PTC_ElementBreakPreDecrease.gameObject, true)
    end
end

--- 隐藏预扣狂暴值的特效
function UIBattlingElementBreakPanel:HidePreDecreaseEffect()
    if self.PTC_ElementBreakPreDecrease then
        KTool.SetActive(self.PTC_ElementBreakPreDecrease.gameObject, false)
    end
end
------------ Function ------------

function UIBattlingElementBreakPanel:IsBossRunning()
    return self.typeShowState == PanelShowState.Running
end

return UIBattlingElementBreakPanel

